import { mintPrincipalToken } from '@projexlight/sdk-principal-token';

// `resolved` is the server-resolved IdentityContext (never request input).
const token = await mintPrincipalToken(resolved, {
  audience: 'sdk-orders',
  ttlSeconds: 120,
  actorKind: 'human',
});
req.headers['x-principal-token'] = token; // forward downstream

import { requirePrincipalToken } from '@projexlight/sdk-principal-token';

app.addHook('preHandler', requirePrincipalToken({ audience: 'sdk-orders' }));

app.get('/orders', async (req) => {
  // req.principal is the verified claims set; forwarded identity headers were stripped.
  return listOrders(req.principal!.tenant_id, req.principal!.scopes);
});

import { startPrincipalKeyRotation } from '@projexlight/sdk-principal-token';

const handle = startPrincipalKeyRotation({
  intervalMs: 24 * 60 * 60 * 1000,
  onRotate: (kid) => audit.emit('principal.signing_key.rotated', { kid }),
});

// force an immediate rotation on suspected compromise:
await handle.rotateNow();
